parameters.text:
=Build a full webpage about this fun fact:

Fact: {{ $json.text }}
Source: {{ $json.source }}
Source URL: {{ $json.source_url }}

parameters.responseBody:
={{ (() => {
  const raw = String($('Build Fun Fact Page').item.json.output || "").trim();
  const fenced = raw.match(/^```(?:html)?\s*([\s\S]*?)\s*```$/i);
  return fenced ? fenced[1].trim() : raw;
})() }}
